for typ,key in [('r+c',lambda p:sum(p)),('r-c',lambda p:p[0]-p[1]),('r',lambda p:p[0]),('c',lambda p:p[1])]:
 d=defaultdict(list)
 for p in patch:d[key(p)].append(p)
 print('\n',typ, sorted((k,len(v),sorted(v)) for k,v in d.items() if len(v)>=3))
# test dihedral transformed seed, uniform integer scales, report bounding fit and overlap max via translations
from itertools import product
coords=[(r-5,c-22) for r,c in seed]
transforms=[]
for swap in (False,True):
 for sx,sy in product((1,-1),repeat=2):
  a=[(sx*(c if swap else r),sy*(r if swap else c)) for r,c in coords]
  minr=min(x for x,y in a); minc=min(y for x,y in a)
  transforms.append(sorted((x-minr,y-minc) for x,y in a))
for t,shape in enumerate(set(tuple(x) for x in transforms)):
 for s in (1,2):
  expanded={(r*s+i,c*s+j) for r,c in shape for i in range(s) for j in range(s)}
  best=(0,None)
  for tr in range(0,13):
   for tc in range(0,15):
    shifted={(r+tr,c+tc) for r,c in expanded}
    n=len(shifted&patch)
    if n>best[0]:best=(n,(tr,tc))
  if best[0]>=5: print('transform',shape,'scale',s,'best',best,'size',len(expanded))

